declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_permission('catalog.manage');if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit;}verify_csrf();$id=(int)($_POST['id']??0);$stmt=db()->prepare('SELECT name_es,is_active FROM service_catalog WHERE id=?');$stmt->execute([$id]);$service=$stmt->fetch();if(!$service){flash('error','Servicio no encontrado.');redirect('service_catalog.php');}$new=$service['is_active']?0:1;db()->prepare('UPDATE service_catalog SET is_active=? WHERE id=?')->execute([$new,$id]);log_activity($new?'Servicio de catálogo activado':'Servicio de catálogo desactivado',null,null,$service['name_es']);flash('success',$new?'Servicio activado.':'Servicio desactivado.');redirect('service_catalog.php');
